package dev.aivillages.e2e.paralleld;
import java.nio.file.*;
import java.util.*;
import java.util.function.*;
import com.google.gson.*;
import com.mojang.brigadier.context.CommandContext;
import com.mojang.brigadier.arguments.StringArgumentType;
import net.fabricmc.api.ModInitializer;
import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.commands.*;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.inventory.*;
import net.minecraft.network.chat.Component;
/** Dedicated two-player test fixture. No production entrypoint or automatic persisted session replay. */
public final class DComponentCampaignServer implements ModInitializer {
 final Map<String,JsonObject> specs=new LinkedHashMap<>();DComponentCase current;DChestCourierScene previous;Path root;String state="IDLE",restoredCase;long due=-1;Runnable pending;int lastOrdinal;
 void later(ServerLevel level,int ticks,Runnable action){if(pending!=null)throw new IllegalStateException("one bounded fixture continuation");due=level.getGameTime()+ticks;pending=action;}
 public void onInitialize(){DTestAuthority.acquireTaggedWorld();try(var stream=getClass().getResourceAsStream("/d10-scenarios.json")){var plan=JsonParser.parseString(new String(stream.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();if(plan.getAsJsonArray("cases").size()!=48)throw new IllegalStateException("complete frozen campaign");for(var r:plan.getAsJsonArray("cases")){var s=r.getAsJsonObject();specs.put(s.get("id").getAsString(),s);}}catch(Exception e){throw new RuntimeException(e);}
  CommandRegistrationCallback.EVENT.register((dispatcher,context,environment)->dispatcher.register(Commands.literal("d-component")
   .then(Commands.literal("area").then(Commands.argument("case",StringArgumentType.word()).executes(c->guard(()->area(c)))))
   .then(Commands.literal("distant-area").executes(c->guard(()->distantArea(c))))
   .then(Commands.literal("prepare").then(Commands.argument("case",StringArgumentType.word()).executes(c->guard(()->prepare(c)))))
   .then(Commands.literal("execute").executes(c->guard(()->{ServerPlayer p=player(c,false);if(!current.phase.equals("READY"))throw new IllegalStateException("one explicit fresh request");current.execute(p);return 1;})))
   .then(Commands.literal("interfere").then(Commands.argument("action",StringArgumentType.word()).executes(c->guard(()->{current.interfere(player(c,true),StringArgumentType.getString(c,"action"));return 1;}))))
   .then(Commands.literal("stop").executes(c->guard(()->{current.stop(player(c,false));return 1;})))
   .then(Commands.literal("travel-budget").executes(c->guard(()->{current.travelBudget(player(c,false));return 1;})))
   .then(Commands.literal("inspect").then(Commands.argument("role",StringArgumentType.word()).executes(c->guard(()->inspect(c)))))
   .then(Commands.literal("probe").executes(c->guard(()->{var p=actualPlayer(c);if(!(current instanceof DComponentStorage s) || s.number!=9)throw new IllegalStateException("privacy probe");var v=current.base.reader.observe(s.scope(p),s.binding.storage());c.getSource().sendSuccess(()->Component.literal(v instanceof dev.aivillages.core.kernel.storage.StorageSnapshot.Visible?"D10_REPLY VISIBLE":"D10_REPLY UNAVAILABLE"),false);return 1;})))
   .then(Commands.literal("save").executes(c->guard(()->save(c))))
   .then(Commands.literal("resume").then(Commands.argument("case",StringArgumentType.word()).executes(c->guard(()->resume(c)))))));
  ServerTickEvents.END_SERVER_TICK.register(server->{if(root==null)return;guard(()->{var level=server.overworld();if(pending!=null && level.getGameTime()>=due){var r=pending;pending=null;r.run();}if(current!=null && !current.terminal)current.tick();return 1;});});
 }
 int guard(IntSupplier action){try{return action.getAsInt();}catch(RuntimeException e){if(root!=null){DComeScene.write(root.resolve("error.json"),Map.of("error",e.toString(),"state",state,"case",current==null?"none":current.id));e.printStackTrace();}state="ERROR";return 0;}}
 static ServerPlayer actualPlayer(CommandContext<CommandSourceStack> c){if(c.getSource().getEntity() instanceof ServerPlayer p)return p;throw new SecurityException("native connected player required");}
 void initializeRoot(){if(root!=null)return;root=Path.of(System.getenv("COGNITIVECRAFT_E2E_DIR")).resolve("server/d10");var persisted=root.resolve("campaign-state.json");if(Files.exists(persisted))lastOrdinal=DObservedParticipants.load(persisted).get("last_ordinal").getAsInt();}
 int area(CommandContext<CommandSourceStack> c){
  if(c.getSource().getEntity()!=null || pending!=null || current!=null && !current.terminal)throw new SecurityException("console-only preparation before component admission");
  initializeRoot();var s=Objects.requireNonNull(specs.get(StringArgumentType.getString(c,"case")));if(s.get("ordinal").getAsInt()!=lastOrdinal+1)throw new IllegalStateException("frozen preparation order");
  var p=s.getAsJsonArray("origin");state="PREPARING_AREA";prepareFloor(c.getSource().getLevel(),s.get("id").getAsString(),new BlockPos(p.get(0).getAsInt(),p.get(1).getAsInt()-1,p.get(2).getAsInt()),20,25,"area-preparation.json",0);return 1;
 }
 int distantArea(CommandContext<CommandSourceStack> c){
  if(c.getSource().getEntity()!=null || pending!=null || current==null || !current.id.equals("D10-MOBILITY-04") || !current.phase.equals("READY"))throw new SecurityException("distant observer preparation before COME admission");
  prepareFloor(c.getSource().getLevel(),current.id,current.origin.offset(99998,-1,100005),5,5,"distant-area-preparation.json",0);return 1;
 }
 void prepareFloor(ServerLevel level,String id,BlockPos low,int width,int depth,String filename,int attempts){
  var a=level.getServer().getPlayerList().getPlayerByName("PlayerD_A");var b=level.getServer().getPlayerList().getPlayerByName("PlayerD_B");if(a==null || b==null || a.level()!=level || b.level()!=level)throw new IllegalStateException("two actual native observer players required");
  boolean loaded=true;var chunks=new ArrayList<Map<String,Object>>();for(int x=low.getX()>>4;x<=(low.getX()+width-1)>>4;x++)for(int z=low.getZ()>>4;z<=(low.getZ()+depth-1)>>4;z++){boolean actual=level.hasChunkAt(new BlockPos(x*16,low.getY(),z*16));loaded&=actual;chunks.add(Map.of("x",x,"z",z,"loaded",actual));}
  if(!loaded){if(attempts>=1000)throw new IllegalStateException("normal player chunks not ready within bounded preparation");later(level,1,()->prepareFloor(level,id,low,width,depth,filename,attempts+1));return;}
  int forced=level.getChunkSource().getForceLoadedChunks().size();var blocks=new ArrayList<Map<String,Object>>();
  for(int x=0;x<width;x++)for(int z=0;z<depth;z++){var p=low.offset(x,0,z);level.setBlockAndUpdate(p,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());blocks.add(Map.of("pos",List.of(p.getX(),p.getY(),p.getZ()),"block",net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(level.getBlockState(p).getBlock()).toString()));}
  if(level.getChunkSource().getForceLoadedChunks().size()!=forced)throw new IllegalStateException("observer preparation changed forced chunks");
  var frame=new TreeMap<String,Object>();frame.put("case",id);frame.put("event","NATIVE_OBSERVER_FLOOR_PREPARED");frame.put("world",DTestAuthority.acquireTaggedWorld().world());frame.put("tick",level.getGameTime());frame.put("chunks",chunks);frame.put("wait_ticks",attempts);frame.put("forced_before",forced);frame.put("forced_after",level.getChunkSource().getForceLoadedChunks().size());frame.put("players",List.of(a.getUUID(),b.getUUID()));frame.put("blocks",blocks);DComeScene.write(root.resolve(id).resolve(filename),frame);System.out.println("CC_D10_PREPARATION "+DComeScene.JSON.toJson(frame));state="IDLE";
 }
 ServerPlayer player(CommandContext<CommandSourceStack> c,boolean second){var p=actualPlayer(c);String expected=second || current instanceof DComponentStorage s && s.number==9?"PlayerD_B":"PlayerD_A";if(!p.getGameProfile().name().equals(expected))throw new SecurityException("actual authenticated fixture caller "+expected);return p;}
 int prepare(CommandContext<CommandSourceStack> c){if(c.getSource().getEntity()!=null || state.equals("PREPARING") || current!=null && !current.terminal)throw new SecurityException("serial console fixture preparation");String id=StringArgumentType.getString(c,"case");JsonObject s=Objects.requireNonNull(specs.get(id));int ordinal=s.get("ordinal").getAsInt();initializeRoot();if(ordinal!=lastOrdinal+1)throw new IllegalStateException("frozen serial campaign order");lastOrdinal=ordinal;DComeScene.write(root.resolve("campaign-state.json"),Map.of("last_ordinal",ordinal,"case",id));state="PREPARING";var server=c.getSource().getServer();var p=server.getPlayerList().getPlayerByName("PlayerD_A");if(p==null || server.getPlayerList().getPlayerByName("PlayerD_B")==null)throw new IllegalStateException("two actual players required");var a=s.getAsJsonArray("origin");var origin=new BlockPos(a.get(0).getAsInt(),a.get(1).getAsInt(),a.get(2).getAsInt());var evidence=root.resolve(id);Consumer<DChestCourierScene> opened=b->{previous=b;later(b.level,40,()->{current=switch(s.get("group").getAsString()){case "storage"->new DComponentStorage(s,b,evidence);case "mobility"->new DComponentMobility(s,b,evidence);case "courier"->new DComponentCourier(s,b,evidence);case "handoff"->new DComponentHandoff(s,b,evidence);default->throw new IllegalStateException();};current.prepare(()->later(b.level,4,()->{current.ready();state="READY";}));});};
  if(previous==null && ordinal>1){var first=root.resolve("D10-STORAGE-01/setup/metadata");DChestCourierScene.openExisting(server.overworld(),origin,p,evidence.resolve("setup"),id,first,opened);}else DChestCourierScene.open(server.overworld(),origin,p,evidence.resolve("setup"),id,previous,id,opened);return 1;}
 int inspect(CommandContext<CommandSourceStack> c){var p=actualPlayer(c);if(!Set.of("PlayerD_A","PlayerD_B").contains(p.getGameProfile().name()))throw new SecurityException("two native fixture observers");String role=StringArgumentType.getString(c,"role");Container nativeInventory;if(current!=null)nativeInventory=current.inspect(role,p);else{var d=DObservedParticipants.load(root.resolve(restoredCase).resolve("participants.json"));var participant=d.getAsJsonObject("participants").entrySet().iterator().next().getValue().getAsJsonObject().getAsJsonObject(role.equals("carrier") && restoredCase.startsWith("D10-HANDOFF")?"sender":role);if(participant.has("entity")){var v=(net.minecraft.world.entity.npc.villager.Villager)c.getSource().getLevel().getEntity(UUID.fromString(participant.get("entity").getAsString()));nativeInventory=v.getInventory();}else{var x=participant.getAsJsonArray("pos");nativeInventory=(Container)c.getSource().getLevel().getBlockEntity(new BlockPos(x.get(0).getAsInt(),x.get(1).getAsInt(),x.get(2).getAsInt()));}}
  int n=nativeInventory.getContainerSize(),rows=(n+8)/9;Container view=n==rows*9?nativeInventory:new CompoundContainer(nativeInventory,new SimpleContainer(rows*9-n){@Override public boolean canPlaceItem(int slot,net.minecraft.world.item.ItemStack stack){return false;}});var type=switch(rows){case 1->MenuType.GENERIC_9x1;case 2->MenuType.GENERIC_9x2;case 3->MenuType.GENERIC_9x3;case 4->MenuType.GENERIC_9x4;case 5->MenuType.GENERIC_9x5;case 6->MenuType.GENERIC_9x6;default->throw new IllegalStateException("bounded native menu");};p.openMenu(new SimpleMenuProvider((id,inventory,observer)->new ChestMenu(type,id,inventory,view,rows),Component.literal("D10 "+role)));return 1;}
 int save(CommandContext<CommandSourceStack> c){if(c.getSource().getEntity()!=null || current==null || !current.phase.equals("AWAIT_NATIVE_SAVE"))throw new SecurityException("witnessed native save fixture");JsonObject d=current instanceof DComponentCourier courier?courier.participants():((DComponentHandoff)current).participants();DComeScene.write(current.evidence.resolve("participants.json"),d);c.getSource().getServer().saveEverything(false,true,true);if(current instanceof DComponentHandoff && DComponentSaveCut.withheld()==0)throw new IllegalStateException("actual native recipient write cut absent");DObservedParticipants.capture(c.getSource().getLevel(),d,"LIVE_AFTER_NATIVE_SAVE",current.evidence,current.id);current.commitFinalFrames();DComeScene.write(current.evidence.resolve("save-ready.json"),Map.of("case",current.id,"tick",c.getSource().getLevel().getGameTime(),"withheld",DComponentSaveCut.withheld(),"receipt",false));return 1;}
 int resume(CommandContext<CommandSourceStack> c){if(c.getSource().getEntity()!=null || current!=null || !state.equals("IDLE"))throw new SecurityException("fresh native process read-only observation");root=Path.of(System.getenv("COGNITIVECRAFT_E2E_DIR")).resolve("server/d10");restoredCase=StringArgumentType.getString(c,"case");var evidence=root.resolve(restoredCase);var d=DObservedParticipants.load(evidence.resolve("participants.json"));lastOrdinal=specs.get(restoredCase).get("ordinal").getAsInt();state="READING";observeReload(c.getSource().getLevel(),d,evidence,0);return 1;}
 void observeReload(ServerLevel level,JsonObject descriptor,Path evidence,int attempts){if(!DObservedParticipants.loaded(level,descriptor)){if(attempts>=1000)throw new IllegalStateException("actual saved native participants did not load within bounded observation preparation");later(level,1,()->observeReload(level,descriptor,evidence,attempts+1));return;}DObservedParticipants.capture(level,descriptor,"FRESH_RESTORED_UNKNOWN",evidence,restoredCase);later(level,100,()->{DObservedParticipants.capture(level,descriptor,"NO_AUTOMATIC_COMPONENT_REPLAY",evidence,restoredCase);DComeScene.write(evidence.resolve("terminal.json"),Map.of("case",restoredCase,"classification","UNKNOWN_NATIVE_PARTICIPANT_PERSISTENCE","active_component_sessions",0,"tick",level.getGameTime()));state="IDLE";});}

}
